<script setup>
defineProps({ suppliers: { type: Array, default: () => [] }, saving: { type: Boolean, default: false } })
defineEmits(['submit', 'cancel'])
const model = defineModel({ required: true })
</script>
<template><form class="product-form" @submit.prevent="$emit('submit')"><div class="form-heading"><div><p class="eyebrow">{{model.id?'UREJANJE':'NOV ARTIKEL'}}</p><h2>{{model.id?model.name:'Dodaj izdelek'}}</h2></div><button type="button" class="icon-close" aria-label="Zapri obrazec" @click="$emit('cancel')">×</button></div><label>Ime<input v-model="model.name" required /></label><div class="two-fields"><label>Kategorija<input v-model="model.category" required /></label><label>Enota<select v-model="model.unit"><option>kos</option><option>kg</option><option>l</option><option>paket</option><option>škatla</option><option>posoda</option><option>vreča</option><option>rola</option></select></label></div><label>Dobavitelj<select v-model="model.supplier_id"><option value="">Brez dobavitelja</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="two-fields"><label>Dobavni rok (dni)<input v-model="model.lead_time_days" type="number" min="0" /></label><label>Varnostna zaloga ({{model.unit}})<input v-model="model.safety_stock_quantity" type="number" min="0" step="0.001" required /></label></div><label class="switch-line"><input v-model="model.active" type="checkbox" /><span>Artikel je aktiven</span></label><div class="form-actions"><button class="secondary" type="button" @click="$emit('cancel')">Prekliči</button><button :disabled="saving">Shrani izdelek</button></div></form></template>
